sp_widget.client_script:
api.controller = function($scope) { 
    $scope.goToRegisterAttendee = function() { 
        var recordProducerSysId = '65a1d427c3036210319033fc05013108'; 
        var url = '/sp?id=record_producer&sys_id=' + recordProducerSysId; 
        window.location.href = url; 
    }; 
};

sp_widget.css:
.custom-action-card-attendee {
    background: linear-gradient(135deg, #e8f5e9, #f1fcf4);
    border-radius: 20px;
    padding: 30px 20px;
    box-shadow: 0 8px 20px rgba(56, 142, 60, 0.1);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}
.custom-action-card-attendee:hover {
    transform: translateY(-8px);
    box-shadow: 0 12px 25px rgba(56, 142, 60, 0.2);
}

.icon-wrapper-attendee {
    background: #388e3c;
    color: white;
    width: 80px;
    height: 80px;
    margin: 0 auto 20px auto;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 36px;
    box-shadow: 0 4px 10px rgba(56, 142, 60, 0.4);
}

.custom-action-card-attendee h4 {
    margin-bottom: 20px;
    font-weight: bold;
    color: #2e7d32;
}

.action-btn-attendee {
    background: #43a047;
    color: white;
    padding: 12px 20px;
    font-size: 16px;
    border: none;
    border-radius: 10px;
    width: 100%;
    transition: background 0.3s ease;
}

.action-btn-attendee:hover {
    background: #2e7d32;
    color: #fff;
}
